<?php require_once 'header.php'; function ef($v) { return htmlspecialchars((string) $v, ENT_QUOTES, 'UTF-8'); } $isEdit = !empty($record); ?>
<main class="content-body"><section class="page-section"><div class="section-title-bar"><div class="section-title"><i class="fa-solid fa-stethoscope"></i> <?php echo $isEdit ? 'Sửa số liệu khám ngoại trú' : 'Nhập số liệu khám ngoại trú'; ?></div><a href="<?php echo XC_URL; ?>/backend/outpatient" class="btn btn-outline"><i class="fa-solid fa-arrow-left"></i> Quay lại</a></div><?php if (!$isEdit): ?><div class="card" style="margin-bottom:18px"><div class="card-header"><div class="card-title"><i class="fa-solid fa-file-excel"></i> Import Excel/CSV</div><a href="<?php echo XC_URL; ?>/backend/outpatient/template" class="btn btn-outline btn-sm"><i class="fa-solid fa-download"></i> Tải file mẫu</a></div><div class="card-body"><form id="outpatientImportForm" method="post" enctype="multipart/form-data" style="display:flex;gap:12px;align-items:center;flex-wrap:wrap"><input type="hidden" name="csrf" value="<?php echo ef($csrf); ?>"><input type="hidden" name="action" value="import"><input type="file" name="import_file" accept=".xlsx,.csv" required><span style="font-size:12px;color:var(--text-muted)">Cột ngày full_date: YYYY-MM-DD hoặc DD/MM/YYYY, tra theo danh mục ngày. Khoa/phòng và đối tượng thanh toán xem trong file mẫu.</span><button class="btn btn-success">Import</button></form><?php if (!empty($flash['message'])): ?><p style="margin-top:12px;color:<?php echo $flash['type']==='success'?'var(--success)':'var(--danger)'; ?>"><?php echo ef($flash['message']); ?></p><?php endif; ?></div></div><?php endif; ?><div id="notice" style="display:none;margin-bottom:18px"></div><div class="card"><div class="card-body"><form id="outpatientForm" class="form-grid" novalidate><input type="hidden" name="csrf" value="<?php echo ef($csrf); ?>"><input type="hidden" name="id" value="<?php echo $isEdit ? (int)$record->id : ''; ?>"><div class="form-group"><label class="form-label">Ngày báo cáo <span class="req">*</span></label><select required class="form-select" name="report_date"><option value="">Chọn ngày trong tháng hiện tại</option><?php $hasSelectedDate = false; foreach ($reportDates as $d): $selected = $isEdit ? (int)$record->report_date === (int)$d->id : $d->full_date === date('Y-m-d'); if ($selected) $hasSelectedDate = true; ?><option value="<?php echo (int)$d->id; ?>" <?php echo $selected ? 'selected' : ''; ?>><?php echo ef(date('d/m/Y', strtotime($d->full_date))); ?></option><?php endforeach; ?></select><small style="color:var(--text-muted)">Chỉ chọn ngày trong tháng <?php echo date('m/Y'); ?>.</small><?php if (!$reportDates || (!$isEdit && !$hasSelectedDate)): ?><small style="color:var(--danger)">Danh mục chưa có ngày hiện tại. Vui lòng bổ sung ioc_date hoặc chọn ngày khác trong tháng.</small><?php elseif ($isEdit && !$hasSelectedDate): ?><small style="color:var(--danger)">Ngày cũ nằm ngoài tháng hiện tại. Vui lòng chọn ngày hợp lệ trước khi lưu.</small><?php endif; ?></div><div class="form-group"><label class="form-label">Khoa/phòng <span class="req">*</span></label><select required class="form-select" name="department_id"><option value="">Chọn khoa/phòng</option><?php foreach($departments as $d): ?><option value="<?php echo $d->id; ?>" <?php echo $isEdit && $record->department_id==$d->id?'selected':''; ?>><?php echo ef($d->department_name); ?></option><?php endforeach; ?></select></div><div class="form-group"><label class="form-label">Đối tượng thanh toán <span class="req">*</span></label><select required class="form-select" name="payer_type_id"><option value="">Chọn đối tượng</option><?php foreach($payerTypes as $p): ?><option value="<?php echo $p->id; ?>" <?php echo $isEdit && $record->payer_type_id==$p->id?'selected':''; ?>><?php echo ef($p->payer_type_name); ?></option><?php endforeach; ?></select></div><?php foreach(array('visit_count'=>'Tổng lượt khám','revisit_count'=>'Lượt tái khám','waiting_count'=>'Đang chờ khám','examining_count'=>'Đang được khám','completed_count'=>'Đã hoàn thành','referral_count'=>'Chuyển tuyến') as $key=>$label): ?><div class="form-group"><label class="form-label"><?php echo $label; ?></label><input class="form-control" type="number" min="0" name="<?php echo $key; ?>" value="<?php echo $isEdit ? (int)$record->$key : 0; ?>"></div><?php endforeach; ?><div class="form-group"><label class="form-label">Thời gian chờ TB (phút)</label><input class="form-control" type="number" min="0" step="0.01" name="avg_wait_minutes" value="<?php echo $isEdit && $record->avg_wait_minutes !== null ? ef($record->avg_wait_minutes) : ''; ?>"></div><div class="form-actions" style="grid-column:1/-1"><a class="btn btn-outline" href="<?php echo XC_URL; ?>/backend/outpatient">Hủy</a><button class="btn btn-primary" id="saveButton"><i class="fa-solid fa-floppy-disk"></i> <?php echo $isEdit ? 'Cập nhật' : 'Lưu số liệu'; ?></button></div></form></div></div></section></main>
<script src="https://code.jquery.com/jquery-3.7.1.min.js"></script><script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script>
<script>
function outpatientNotice(message, success) {
    Swal.fire({icon:success?'success':'error',title:success?'Thành công':'Không thành công',text:message,timer:success?1500:0,showConfirmButton:!success});
}
function submitOutpatient(form, action, multipart) {
    if (!form.checkValidity()) { form.reportValidity(); return; }
    var buttons=$(form).find('button').prop('disabled',true);
    var options={url:'<?php echo XC_URL; ?>/api/'+action,type:'POST',dataType:'json',data:multipart?new FormData(form):$(form).serialize()};
    if(multipart){options.processData=false;options.contentType=false;}
    $.ajax(options).done(function(res){
        outpatientNotice(res.message,res.success);
        if(res.success && !multipart) setTimeout(function(){location.href='<?php echo XC_URL; ?>/backend/outpatient';},1100);
        if(res.success && multipart){$(form).find('input[type=file]').val('');}
    }).fail(function(xhr){outpatientNotice(xhr.responseJSON&&xhr.responseJSON.message?xhr.responseJSON.message:'Không thể kết nối máy chủ. Vui lòng thử lại.',false);}).always(function(){buttons.prop('disabled',false);});
}
$('#outpatientForm').on('submit',function(e){e.preventDefault();submitOutpatient(this,'<?php echo $isEdit ? 'editOutpatient' : 'saveOutpatient'; ?>',false);});
$('#outpatientImportForm').on('submit',function(e){e.preventDefault();var file=this.import_file.files[0];if(!file||! /\.(xlsx|csv)$/i.test(file.name)||file.size>5*1024*1024){outpatientNotice('Chọn tệp .xlsx/.csv không quá 5 MB.',false);return;}submitOutpatient(this,'importOutpatient',true);});
</script><?php require_once 'footer.php'; ?>
